export function calculateLoan({amount,rate,months,date,extra=0}){let p=Number(amount),annual=Number(rate),n=Number(months),prepay=Number(extra),base=new Date(date+'T12:00:00');if(!(p>=1000&&p<=1e9&&annual>=0&&annual<=60&&Number.isInteger(n)&&n>=1&&n<=600&&prepay>=0&&prepay<=1e9&&Number.isFinite(base.getTime())))return null;let r=annual/1200,emi=r?p*r/(-Math.expm1(-n*Math.log1p(r))):p/n;function build(extra){let balance=p,rows=[];for(let i=0;i<n&&balance>1e-7;i++){let interest=balance*r,principal=Math.min(balance,Math.max(0,emi-interest)+extra),payment=principal+interest;balance=Math.max(0,balance-principal);let d=new Date(base);d.setDate(1);d.setMonth(d.getMonth()+i+1);d.setDate(Math.min(base.getDate(),new Date(d.getFullYear(),d.getMonth()+1,0).getDate()));rows.push({month:i+1,date:d.toLocaleDateString('en-IN'),payment,principal,interest,balance})}return rows}let baseline=build(0),rows=prepay?build(prepay):baseline,total=rows.reduce((n,t)=>n+t.payment,0),interest=rows.reduce((n,t)=>n+t.interest,0),baselineInterest=baseline.reduce((n,t)=>n+t.interest,0);return{emi,monthly:emi+prepay,rows,total,interest,baselineInterest,savedInterest:Math.max(0,baselineInterest-interest),savedMonths:n-rows.length,principal:p,actualMonths:rows.length}}
